//autogenerated:yes
//nolint:revive,govet,errcheck
package csairlink_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/csairlink"
)

func TestEnum_AIRLINK_AUTH_RESPONSE_TYPE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.AIRLINK_AUTH_RESPONSE_TYPE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.AIRLINK_ERROR_LOGIN_OR_PASS.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.AIRLINK_AUTH_RESPONSE_TYPE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.AIRLINK_ERROR_LOGIN_OR_PASS, dec)
	})
}
